const listDeploymentsToConverge = `-- name: ListDeploymentsToConverge :many
SELECT d.id, d.app_id, d.number, d.status, d.source_key, d.source_sha256, d.source_size, d.upload_expires_at, d.image_digest, d.created_by, d.failure_reason, d.cancel_requested_at, d.enqueued_at, d.created_at, d.uploading_at, d.queued_at, d.building_at, d.built_at, d.failed_at, d.cancelled_at, d.source_deleted_at, d.image_deleted_at, d.kind, d.image_of_deployment_id, d.rollback_to, d.env_snapshot_id, d.deploying_at, d.live_at, d.superseded_at, d.rolled_back_at FROM deployments d
JOIN apps a ON a.current_deployment_id = d.id
WHERE d.status = 'live' AND (d.enqueued_at IS NULL OR d.enqueued_at < $1)
  AND (
      ((a.desired_state = 'stopped' OR a.deleted_at IS NOT NULL) AND EXISTS (
          SELECT 1 FROM app_instances i
          WHERE i.deployment_id = d.id AND i.state IN ('starting', 'healthy', 'unhealthy', 'stopping')
      ))
      OR (a.desired_state = 'running' AND a.deleted_at IS NULL AND a.sleeping_since IS NULL
          AND NOT EXISTS (
              SELECT 1 FROM app_instances i
              WHERE i.deployment_id = d.id AND i.state IN ('starting', 'healthy', 'unhealthy', 'stopping')
          )
          AND NOT EXISTS (
              SELECT 1 FROM app_instances i
              WHERE i.deployment_id = d.id AND i.state IN ('crashed', 'failed') AND i.created_at >= a.desired_state_at
          ))
  )
ORDER BY d.created_at
LIMIT $2
`

