const retireLive = `-- name: RetireLive :many
UPDATE deployments
SET status = $1::deployment_status,
    superseded_at = CASE WHEN $1::deployment_status = 'superseded' THEN now() ELSE superseded_at END,
    rolled_back_at = CASE WHEN $1::deployment_status = 'rolled_back' THEN now() ELSE rolled_back_at END
WHERE app_id = $2 AND status = 'live'
RETURNING id, number
`

type RetireLiveParams struct {
	Status DeploymentStatus
	AppID  uuid.UUID
}

type RetireLiveRow struct {
	ID     uuid.UUID
	Number int32
}

// The app's live deployment is replaced: superseded by a new release, or
// rolled_back when the new release is a rollback.
func (q *Queries) RetireLive(ctx context.Context, arg RetireLiveParams) ([]RetireLiveRow, error) {
	rows, err := q.db.Query(ctx, retireLive, arg.Status, arg.AppID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []RetireLiveRow{}
	for rows.Next() {
		var i RetireLiveRow
		if err := rows.Scan(&i.ID, &i.Number); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

