const upsertAppEnv = `-- name: UpsertAppEnv :exec
INSERT INTO app_env (app_id, key, value, key_version, is_secret, updated_by, updated_at)
VALUES ($1, $2, $3, $4, $5, $6, now())
ON CONFLICT (app_id, key) DO UPDATE
SET value = EXCLUDED.value, key_version = EXCLUDED.key_version, is_secret = EXCLUDED.is_secret,
    updated_by = EXCLUDED.updated_by, updated_at = now()
`

type UpsertAppEnvParams struct {
	AppID      uuid.UUID
	Key        string
	Value      []byte
	KeyVersion int32
	IsSecret   bool
	UpdatedBy  *uuid.UUID
}

func (q *Queries) UpsertAppEnv(ctx context.Context, arg UpsertAppEnvParams) error {
	_, err := q.db.Exec(ctx, upsertAppEnv,
		arg.AppID,
		arg.Key,
		arg.Value,
		arg.KeyVersion,
		arg.IsSecret,
		arg.UpdatedBy,
	)
	return err
}

const workspaceReservedMemory = `-- name: WorkspaceReservedMemory :one
SELECT coalesce(sum(memory_mb), 0)::bigint AS memory_mb FROM app_instances
WHERE workspace_id = $1 AND app_id <> $2
  AND state IN ('starting', 'healthy', 'unhealthy', 'stopping')
`

type WorkspaceReservedMemoryParams struct {
	WorkspaceID uuid.UUID
	ExceptAppID uuid.UUID
}

// Memory reserved by a workspace's instances, not counting one app (whose
// old and new versions overlap during a rollout).
func (q *Queries) WorkspaceReservedMemory(ctx context.Context, arg WorkspaceReservedMemoryParams) (int64, error) {
	row := q.db.QueryRow(ctx, workspaceReservedMemory, arg.WorkspaceID, arg.ExceptAppID)
	var memory_mb int64
	err := row.Scan(&memory_mb)
	return memory_mb, err
}
